is_valid_palindrome : ℕ → Prop :=
  fun n =>
    100 ≤ n ∧
      n ≤ 999 ∧
        let a := n / 100;
        let b := n % 100 / 10;
        let c := n % 10;
        a = c ∧ b - a = a - b
valid_palindromes : Finset ℕ := Finset.filter (fun n => is_valid_palindrome n) (Finset.range 1000)
⊢ valid_palindromes.sum id / valid_palindromes.card = 555

⊢ let people := {0, 1, 2, 3, 4};
  let cooking_time := ![5, 7, 1, 12, 5];
  let bob := 1;
  let wait_time := fun order person =>
    cooking_time person +
      ∑ p ∈ Finset.filter (fun p => order p < order person ∧ cooking_time p > cooking_time person) people, 0;
  let true_wait_time := fun order person =>
    let start_time := ∑ p ∈ Finset.filter (fun p => order p < order person) people, cooking_time p;
    start_time + cooking_time person;
  let expected_bob_wait := ↑(∑ perm : Equiv.Perm (Fin 5), true_wait_time perm bob) / ↑5!;
  expected_bob_wait = 37 / 2

